import {anonymousUserHandler, bff} from '@smart/feature-app/node';
import {
  PRICE_TYPE,
  salesChannelSchema,
  stringToBooleanSchema,
} from '@smart/types';
import {Config} from 'sst/node/config';
import {z} from 'zod';
import {refreshCart} from '../utils';
import {convertCartPrice} from '../utils/convert-cart-price';
import {logger} from '../utils/logger';
import {updatePaymentType} from '../utils/update-payment-type';
import {bodyParamsStruct} from './body-params';
import {paymentTypesMapping} from './update-payment.model';

export const queryParamsSchema = z.object({
  salesChannel: salesChannelSchema,
  enableAnonymousFlow: stringToBooleanSchema,
  priceType: z.enum([PRICE_TYPE.COMMERCIAL, PRICE_TYPE.PRIVATE]),
});

export const handler = bff(
  async ({
    envName,
    preview,
    rotatingVerifySecret,
    aws,
    language,
    user,
    adb,
    baseSiteId,
    queryParams: {salesChannel, enableAnonymousFlow, priceType},
    body: {cartEntryNumber, mode, params},
    cart,
    endpoints,
  }) => {
    const result = anonymousUserHandler({
      user,
      enableAnonymousFlow,
      cart,
    });

    if (!result) {
      return {
        statusCode: 200,
        headers: {
          'Content-Type': `application/json`,
          'Cache-Control': `private, no-store`,
        },
        body: JSON.stringify({}),
      };
    }
    const {cartId, userId} = result;

    const auth = {
      ...user,
      userId,
    };

    await updatePaymentType({
      envName,
      baseSiteId,
      userId,
      cartId,
      cartEntryNumber: cartEntryNumber.toString(),
      paymentType: paymentTypesMapping[mode],
      fields: `FULL`,
      advancePayment: params?.advancePayment,
      advanceMonth: params?.advanceMonth,
      duration: params?.duration,
      mileage: params?.mileage,
      language,
      salesChannel,
      customerId: adb?.customerUserId,
    });

    logger.info(
      {
        advancePayment: params?.advancePayment,
        advanceMonth: params?.advanceMonth,
        duration: params?.duration,
        mileage: params?.mileage,
      },
      `Payment type updated`,
    );

    if (userId === `anonymous`) {
      await convertCartPrice({
        baseSiteId,
        configuration: endpoints.ecom,
        convertCart: priceType === PRICE_TYPE.COMMERCIAL,
        extraHeaders: {
          anonymousCartGuid: cartId,
          baseSiteId,
          cartId,
          userId,
        },
      });
    }

    return await refreshCart(auth, adb, {
      awsRequestId: aws.context.awsRequestId,
      baseSiteId,
      cartId,
      customerType: priceType,
      envName,
      language,
      preview,
      rotatingVerifySecret,
      salesChannel,
      userId,
    });
  },
  {
    auth: false,
    schema: {queryParams: queryParamsSchema, body: bodyParamsStruct},
    fetchEndpoints: true,
    logger,
    staticVerifySecret: JSON.stringify({
      headerName: `x-api-key`,
      headerValue: Config.ENDPOINT_DIRECTORY_API_KEY,
    }),
  },
);

